package com.limagiran.holyrics.vlc;

import com.limagiran.holyrics.model.theme.Theme;
import com.limagiran.holyrics.util.BooleanOptional;
import com.limagiran.holyrics.util.RWObj;
import com.limagiran.holyrics.util.Utils;
import com.limagiran.holyrics.util.Values;
import com.limagiran.holyrics.view.PresentationJDialog;
import java.awt.Color;
import java.awt.Rectangle;
import java.awt.Dialog.ModalExclusionType;
import java.awt.event.ComponentEvent;
import java.awt.event.ComponentListener;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Map.Entry;
import java.util.function.Consumer;
import javax.swing.JDialog;
import javax.swing.SwingUtilities;
import uk.co.caprica.vlcj.component.EmbeddedMediaPlayerComponent;

public class VLCVideoBackgroundBase extends JDialog implements ComponentListener {
   private static VLCVideoBackgroundBase INSTANCE;
   private static final Map<Float, Map<Float, Integer>> MAP_PROGRESS = loadMap();
   private static List<Entry<Float, Map<Float, Integer>>> MAP_ENTRY_SET;
   private final VLCVideoBackground vlcView;
   protected PresentationJDialog dialog;
   private volatile float opacity;
   private volatile boolean show;
   private volatile boolean stopped;

   private static synchronized List<Entry<Float, Map<Float, Integer>>> getMapEntrySet() {
      if (MAP_ENTRY_SET == null) {
         MAP_ENTRY_SET = new ArrayList<>(MAP_PROGRESS.entrySet());
      }

      return MAP_ENTRY_SET;
   }

   private VLCVideoBackgroundBase(EmbeddedMediaPlayerComponent mediaView) {
      this.setUndecorated(true);
      this.vlcView = new VLCVideoBackground(this, mediaView);
      this.initComponents();
      this.init();
   }

   private void init() {
      this.getContentPane().setBackground(Values.COLOR_TRANSPARENT);
      this.setOpacity(0.0F);
      this.setFocusable(false);
      this.setFocusableWindowState(false);
      this.setAlwaysOnTop(true);
      this.setModalExclusionType(ModalExclusionType.APPLICATION_EXCLUDE);
      this.addMouseListener(new MouseAdapter() {
         @Override
         public void mousePressed(MouseEvent e) {
            VLCVideoBackgroundBase.this.runIfDialogIsNotNull(d -> {
               d.toFront();
               d.requestFocus();
            });
         }
      });
      this.setVisible(true);
   }

   private void initComponents() {
      this.setDefaultCloseOperation(0);
      this.setResizable(false);
      this.pack();
      this.setLocationRelativeTo(null);
   }

   public static VLCVideoBackgroundBase main(PresentationJDialog dialog) {
      EmbeddedMediaPlayerComponent mediaView = VLC.getBackgroundPresentationView();
      if (mediaView == null) {
         return null;
      } else {
         if (INSTANCE == null) {
            INSTANCE = new VLCVideoBackgroundBase(mediaView);
         }

         INSTANCE.setup(dialog);
         return INSTANCE;
      }
   }

   @Override
   public void setBounds(Rectangle bounds) {
      super.setBounds(bounds);
      this.runVLCNotNull(vlc -> vlc.setBounds(bounds));
   }

   private void runVLCNotNull(Consumer<VLCVideoBackground> vlc) {
      BooleanOptional.runIfTrue(this.vlcView != null, () -> vlc.accept(this.vlcView));
   }

   public void setShow(boolean show) {
      this.show = show;
      if (!this.show) {
         Utils.startThreadDaemon(() -> this.fadeOut(this.opacity));
      } else {
         this.setOpacity(this.opacity);
      }
   }

   public void play(Theme theme) {
      this.setContentPaneBackground(theme.getTransparencyColor());
      this.runVLCNotNull(vlc -> vlc.play(theme));
   }

   public void stop() {
      this.runVLCNotNull(vlc -> vlc.stop());
   }

   @Override
   public void revalidate() {
      super.revalidate();
      this.runVLCNotNull(vlc -> vlc.getContentPane().revalidate());
   }

   @Override
   public void setOpacity(float opacity) {
      this.opacity = opacity;
      double maxOp = this.vlcView == null ? 1.0 : this.vlcView.maxOpacity;
      float alpha = searchMap(maxOp, opacity);
      SwingUtilities.invokeLater(() -> {
         if (this.show) {
            Utils.safeException(() -> super.setOpacity(alpha));
            this.runVLCNotNull(vlc -> vlc.setOpacity(opacity));
         } else {
            Utils.safeException(() -> super.setOpacity(0.0F));
            this.runVLCNotNull(vlc -> vlc.setOpacity(0.0F));
         }

         if (opacity == 0.0F || opacity == 1.0F) {
            this.repaint();
            this.runVLCNotNull(vlc -> vlc.repaint());
         }
      });
   }

   @Override
   public void setVisible(boolean flag) {
      super.setVisible(flag);
      this.runVLCNotNull(vlc -> vlc.setVisible(flag));
   }

   @Override
   public void dispose() {
      super.dispose();
      this.runVLCNotNull(vlc -> vlc.dispose());
   }

   private void fadeOut(float opacity) {
      long fps = 50L;
      long duration = 1000L;
      float[] array = new float[Math.max(20, 2)];
      array[0] = opacity;
      int lastIndex = array.length - 1;
      array[array.length - 1] = 0.0F;
      float ratio = opacity / (float)lastIndex;

      for (int i = 1; i < lastIndex; i++) {
         array[i] = Math.max(array[i - 1] - ratio, 0.0F);
      }

      for (float f : array) {
         if (this.show) {
            break;
         }

         SwingUtilities.invokeLater(() -> super.setOpacity(this.show ? this.opacity : f));
         Utils.sleep(f > 0.5F ? 60L : 41L);
      }
   }

   private void setup(PresentationJDialog dialog) {
      this.show = false;
      this.dialog = dialog;
      this.stopped = false;
      if (dialog != null) {
         dialog.removeComponentListener(this);
         dialog.addComponentListener(this);
         this.runVLCNotNull(vlc -> vlc.setup(dialog));
         this.setContentPaneBackground(Values.COLOR_TRANSPARENT);
         this.setOpacity(0.0F);
         this.setVisible(true);
         this.repaint();
      }
   }

   @Override
   public void componentResized(ComponentEvent e) {
      this.runIfDialogIsNotNull(d -> this.setBounds(d.getBounds()));
   }

   @Override
   public void componentMoved(ComponentEvent e) {
      this.runIfDialogIsNotNull(d -> this.setBounds(d.getBounds()));
   }

   @Override
   public void componentShown(ComponentEvent e) {
   }

   @Override
   public void componentHidden(ComponentEvent e) {
   }

   protected void runIfDialogIsNotNull(Consumer<PresentationJDialog> consumer) {
      PresentationJDialog _dialog = this.dialog;
      if (_dialog != null) {
         consumer.accept(_dialog);
      }
   }

   public boolean isStopped() {
      return this.stopped;
   }

   private static Map<Float, Map<Float, Integer>> loadMap() {
      String base64 = "";
      Map map = RWObj.read(
         Utils.base64ToBytes(
            ""
         ),
         Map.class
      );
      if (map == null) {
         map = VLCVideoBackgroundBaseUtils.generateMapAlphaColor();
      }

      return map;
   }

   public static float searchMap(double opacity, float progress) {
      if (opacity > 0.96 || progress < 0.002F) {
         return 0.0F;
      } else if (!(opacity < 0.04) && !(progress > 0.99F)) {
         Entry<Float, Map<Float, Integer>> last = null;
         Entry<Float, Map<Float, Integer>> found = null;

         for (Entry<Float, Map<Float, Integer>> e : getMapEntrySet()) {
            if ((double)e.getKey().floatValue() > opacity) {
               found = last != null ? last : e;
               break;
            }

            last = e;
         }

         if (found == null) {
            found = last;
         }

         if (found == null) {
            return progress;
         } else {
            Entry<Float, Integer> last2 = null;
            Entry<Float, Integer> found2 = null;

            for (Entry<Float, Integer> e : found.getValue().entrySet()) {
               if (e.getKey() > progress) {
                  found2 = last2 != null ? last2 : e;
                  break;
               }

               last2 = e;
            }

            if (found2 == null) {
               found2 = last2;
            }

            return found2 != null ? (float)found2.getValue().intValue() / 255.0F : progress;
         }
      } else {
         return 1.0F;
      }
   }

   private void setContentPaneBackground(Color c) {
      this.getContentPane().setBackground(new Color(c.getRed(), c.getGreen(), c.getBlue(), 254));
   }
}
